// Simple test script for the /check endpoint

const app = require('./app');
const request = require('supertest');

// Test the /check endpoint with a simple rule
async function testCheckEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Simple numeric comparison
  const test1 = {
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  };

  console.log('Test 1:', JSON.stringify(test1, null, 2));
  const response1 = await request(app)
    .post('/check')
    .send(test1)
    .expect('Content-Type', /json/);

  console.log('Response 1:', JSON.stringify(response1.body, null, 2));
  console.log('\n---\n');

  // Test 2: Using req object in rule
  const test2 = {
    rule: 'ctx.userId === req.body.context.userId',
    context: { userId: '123' }
  };

  console.log('Test 2:', JSON.stringify(test2, null, 2));
  const response2 = await request(app)
    .post('/check')
    .send(test2)
    .expect('Content-Type', /json/);

  console.log('Response 2:', JSON.stringify(response2.body, null, 2));
  console.log('\n---\n');

  // Test 3: Invalid rule (should error)
  const test3 = {
    rule: 'invalid javascript syntax {',
    context: { amount: 150 }
  };

  console.log('Test 3 (should error):', JSON.stringify(test3, null, 2));
  const response3 = await request(app)
    .post('/check')
    .send(test3)
    .expect('Content-Type', /json/)
    .expect(400);

  console.log('Response 3:', JSON.stringify(response3.body, null, 2));
  console.log('\n---\n');

  // Test 4: Missing rule (should error)
  const test4 = {
    context: { amount: 150 }
  };

  console.log('Test 4 (missing rule):', JSON.stringify(test4, null, 2));
  const response4 = await request(app)
    .post('/check')
    .send(test4)
    .expect('Content-Type', /json/)
    .expect(400);

  console.log('Response 4:', JSON.stringify(response4.body, null, 2));
}

// Run the test
if (require.main === module) {
  const server = app.listen(3001, async () => {
    console.log('Test server running on port 3001');
    try {
      await testCheckEndpoint();
    } catch (error) {
      console.error('Test failed:', error);
    } finally {
      server.close();
      process.exit(0);
    }
  });
}

// Simple test to verify the evalRule function logic

// Mock implementation based on the actual code
function mockEvalRule(reqBody) {
  const expr = reqBody.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: reqBody.context, req: { body: reqBody } };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, ctx.req); // dynamic eval
}

// Test cases
console.log('Testing evalRule function logic:\n');

// Test 1: Simple numeric comparison
const test1 = {
  rule: 'ctx.amount > 100',
  context: { amount: 150 }
};

try {
  const result1 = mockEvalRule(test1);
  console.log('Test 1:', JSON.stringify(test1, null, 2));
  console.log('Result 1:', result1, '(expected: true)\n');
} catch (error) {
  console.log('Test 1 failed:', error.message);
}

// Test 2: Simple numeric comparison (false case)
const test2 = {
  rule: 'ctx.amount > 100',
  context: { amount: 50 }
};

try {
  const result2 = mockEvalRule(test2);
  console.log('Test 2:', JSON.stringify(test2, null, 2));
  console.log('Result 2:', result2, '(expected: false)\n');
} catch (error) {
  console.log('Test 2 failed:', error.message);
}

// Test 3: Logical AND operation
const test3 = {
  rule: 'ctx.amount > 100 && ctx.user === "admin"',
  context: { amount: 150, user: 'admin' }
};

try {
  const result3 = mockEvalRule(test3);
  console.log('Test 3:', JSON.stringify(test3, null, 2));
  console.log('Result 3:', result3, '(expected: true)\n');
} catch (error) {
  console.log('Test 3 failed:', error.message);
}

// Test 4: Accessing req object
const test4 = {
  rule: 'ctx.userId === req.body.context.userId',
  context: { userId: '123' }
};

try {
  const result4 = mockEvalRule(test4);
  console.log('Test 4:', JSON.stringify(test4, null, 2));
  console.log('Result 4:', result4, '(expected: true)\n');
} catch (error) {
  console.log('Test 4 failed:', error.message);
}

// Test 5: Invalid syntax should throw error
const test5 = {
  rule: 'invalid javascript syntax {',
  context: { amount: 150 }
};

try {
  const result5 = mockEvalRule(test5);
  console.log('Test 5:', JSON.stringify(test5, null, 2));
  console.log('Result 5:', result5, '(should have thrown error)\n');
} catch (error) {
  console.log('Test 5 (expected error):', error.message.substring(0, 100) + '...\n');
}

console.log('All tests completed!');

