// Run the app and test it with a simple request

const app = require('./app');

// Start the server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');

  // Make a test request after a short delay
  setTimeout(() => {
    const http = require('http');

    const postData = JSON.stringify({
      rule: 'ctx.amount > 100 && ctx.user === "admin"',
      context: { amount: 150, user: 'admin' }
    });

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/check',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      console.log(`\nTest request to /check:`);
      console.log(`Status Code: ${res.statusCode}`);

      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        console.log(`Response Body: ${data}`);

        // Parse and pretty print
        try {
          const parsed = JSON.parse(data);
          console.log('\nParsed response:');
          console.log(JSON.stringify(parsed, null, 2));
        } catch (e) {
          console.log('Could not parse JSON:', e.message);
        }

        // Also test /health endpoint
        console.log('\n---\nTesting /health endpoint:');
        http.get('http://localhost:3000/health', (healthRes) => {
          let healthData = '';
          healthRes.on('data', (chunk) => {
            healthData += chunk;
          });
          healthRes.on('end', () => {
            console.log(`Status: ${healthRes.statusCode}`);
            console.log(`Response: ${healthData}`);

            // Stop the server after testing
            setTimeout(() => {
              console.log('\nStopping server...');
              server.close();
              process.exit(0);
            }, 1000);
          });
        }).on('error', (err) => {
          console.error('Health check error:', err.message);
          server.close();
          process.exit(1);
        });
      });
    });

    req.on('error', (err) => {
      console.error('Request error:', err.message);
      server.close();
      process.exit(1);
    });

    req.write(postData);
    req.end();

  }, 1000); // Wait 1 second for server to start
});

// Handle server errors
server.on('error', (err) => {
  console.error('Server error:', err.message);
  process.exit(1);
});

