    name: "Simple numeric comparison false",
    body: JSON.stringify({
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    }),
    expected: false
  },
  {
    name: "String comparison",
    body: JSON.stringify({
      rule: 'ctx.user === "admin"',
      context: { user: "admin" }
    }),
    expected: true
  },
  {
    name: "Complex logical expression",
    body: JSON.stringify({
      rule: 'ctx.score >= 80 && ctx.attendance > 75',
      context: { score: 85, attendance: 80 }
    }),
    expected: true
  },
  {
    name: "Access request properties",
    body: JSON.stringify({
      rule: 'req.method === "POST" && ctx.id === 123',
      context: { id: 123 }
    }),
    expected: true
  }
];

// Start the server if not already running
const app = require('./app.js');

// Note: The app is already listening on port 3000 from app.js
// In a real test, we would start/stop the server, but for simplicity
// we'll assume it's running

console.log('Testing POST /check endpoint...\n');

// Function to send a POST request
function sendTestRequest(testCase, callback) {
  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(testCase.body)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      try {
        const parsed = JSON.parse(data);
        callback(null, parsed, res.statusCode);
      } catch (e) {
        callback(e, null, res.statusCode);
      }
    });
  });

  req.on('error', (e) => {
    callback(e, null, null);
  });

  req.write(testCase.body);
  req.end();
}

