// POST /check endpoint for evaluating rule expressions
app.post('/check', (req, res) => {
  try {
    // Check if rule is provided in the request body
    if (!req.body || !req.body.rule) {
      return res.status(400).json({ error: 'Missing rule expression in request body' });
    }

    // Evaluate the rule using the evalRule function
    const result = evalRule(req);

    // Return the evaluation result
    return res.json({ 
      result: result,
      rule: req.body.rule,
      context: req.body.context || {}
    });
  } catch (error) {
    // Handle any errors during rule evaluation
    return res.status(400).json({ 
      error: 'Rule evaluation failed', 
      message: error.message,
      rule: req.body.rule 
    });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
